package lineup

import (
	"encoding/json"
	"math"
	"os"
	"reflect"
	"testing"
)

type fixture struct {
	Tie   float64 `json:"tie"`
	Cases []struct {
		Name    string `json:"name"`
		Members []struct {
			ID      string   `json:"id"`
			Ability *float64 `json:"ability"`
			Cost    *float64 `json:"cost"`
		} `json:"members"`
		Expect *Lineup `json:"expect"`
	} `json:"cases"`
}

// The fixture is generated by clients/design-kit/lineup.js; Go must agree with it exactly.
func TestMatchesReferenceFixture(t *testing.T) {
	b, err := os.ReadFile("testdata/lineup-v1.json")
	if err != nil {
		t.Fatal(err)
	}
	var f fixture
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	if f.Tie != Tie {
		t.Fatalf("fixture tie %v != Tie %v", f.Tie, Tie)
	}
	for _, c := range f.Cases {
		t.Run(c.Name, func(t *testing.T) {
			var ms []Member
			for _, m := range c.Members {
				ms = append(ms, Member{ID: m.ID, Ability: m.Ability, Cost: m.Cost})
			}
			got := Compute(ms, f.Tie)
			if (got == nil) != (c.Expect == nil) {
				t.Fatalf("got %v, want %v", got, c.Expect)
			}
			if got == nil {
				return
			}
			want := c.Expect
			if got.Baseline != want.Baseline || !reflect.DeepEqual(got.Frontier, want.Frontier) {
				t.Fatalf("baseline/frontier = %s %v, want %s %v", got.Baseline, got.Frontier, want.Baseline, want.Frontier)
			}
			if len(got.Steps) != len(want.Steps) {
				t.Fatalf("steps = %v, want %v", got.Steps, want.Steps)
			}
			for i := range got.Steps {
				g, w := got.Steps[i], want.Steps[i]
				if g.From != w.From || g.To != w.To || !near(g.AbilityDelta, w.AbilityDelta) || !near(g.CostRatio, w.CostRatio) {
					t.Fatalf("step %d = %+v, want %+v", i, g, w)
				}
			}
			if len(got.Members) != len(want.Members) {
				t.Fatalf("members = %d, want %d", len(got.Members), len(want.Members))
			}
			for i, g := range got.Members {
				w := want.Members[i]
				if g.ID != w.ID || g.Status != w.Status || !reflect.DeepEqual(g.Tags, w.Tags) || !reflect.DeepEqual(g.DominatedBy, w.DominatedBy) {
					t.Fatalf("member %s = %+v %+v, want %+v %+v", g.ID, g, g.DominatedBy, w, w.DominatedBy)
				}
				if g.Status == "" && !near(g.CostRelative, w.CostRelative) {
					t.Fatalf("member %s costRelative = %v, want %v", g.ID, g.CostRelative, w.CostRelative)
				}
			}
		})
	}
}

func near(a, b float64) bool { return math.Abs(a-b) <= 1e-9*math.Max(1, math.Abs(b)) }
